  return (
    <DateInput.Root granularity="minute" formatter={formatter} maxW="sm">
      <DateInput.Label>Appointment time</DateInput.Label>
      <DateInput.Control>
        <DateInput.Segments />
      </DateInput.Control>
      <DateInput.HiddenInput />
    </DateInput.Root>
  )
}

"use client";

import { Checkbox, DateInput, HStack, Stack } from "@chakra-ui/react"
import { parseZonedDateTime } from "@internationalized/date"
import { useState } from "react"

export const DateInputTimeZone = () => {
  const [hour12, setHour12] = useState(true)
  const [hideTimeZone, setHideTimeZone] = useState(false)

  return (
    <Stack gap="4" maxW="sm">
      <DateInput.Root
        defaultValue={[
          parseZonedDateTime("2026-02-03T08:45:00[America/Los_Angeles]"),
        ]}
        timeZone="America/Los_Angeles"
        granularity="minute"
        hourCycle={hour12 ? 12 : 24}
        hideTimeZone={hideTimeZone}
      >
        <DateInput.Label>Meeting time</DateInput.Label>
        <DateInput.Control>
          <DateInput.Segments />
        </DateInput.Control>
        <DateInput.HiddenInput />
      </DateInput.Root>

      <HStack gap="4">
        <Checkbox.Root
          size="sm"
          checked={hour12}
          onCheckedChange={(e) => setHour12(!!e.checked)}
        >
          <Checkbox.HiddenInput />
          <Checkbox.Control />
          <Checkbox.Label>12 hour</Checkbox.Label>
        </Checkbox.Root>
        <Checkbox.Root
          size="sm"
          checked={hideTimeZone}
          onCheckedChange={(e) => setHideTimeZone(!!e.checked)}
        >
          <Checkbox.HiddenInput />
          <Checkbox.Control />
          <Checkbox.Label>Hide time zone</Checkbox.Label>
        </Checkbox.Root>
      </HStack>
    </Stack>
  )
}

"use client";

import { DateInput, IconButton, useDateInputContext } from "@chakra-ui/react"
import { parseDate } from "@internationalized/date"
import { LuX } from "react-icons/lu"

const ClearTrigger = () => {
  const dateInput = useDateInputContext()

  if (!dateInput.value.length) return null

  return (
    <IconButton
      aria-label="Clear date"
      variant="ghost"
      size="xs"
      onClick={() => dateInput.clearValue()}
    >
      <LuX />
    </IconButton>
  )
}

export const DateInputWithClearTrigger = () => {
  return (
    <DateInput.Root defaultValue={[parseDate("2026-01-26")]} maxW="sm">
      <DateInput.Label>Date of birth</DateInput.Label>
      <DateInput.Control gap="2">
        <DateInput.Segments />
        <ClearTrigger />
      </DateInput.Control>
      <DateInput.HiddenInput />
    </DateInput.Root>
  )
}

"use client";

import { Button, DateInput, Field, Input, Stack } from "@chakra-ui/react"
import { standardSchemaResolver } from "@hookform/resolvers/standard-schema"
import { Controller, useForm } from "react-hook-form"
import { z } from "zod"

const formSchema = z.object({
  name: z.string().min(1, { message: "Name is required" }),
  dob: z.array(z.any()).min(1, { message: "Date of birth is required" }),
})

type FormValues = z.infer<typeof formSchema>

export const DateInputWithHookForm = () => {
  const { handleSubmit, control, formState } = useForm<FormValues>({
    resolver: standardSchemaResolver(formSchema),
    defaultValues: { dob: [] },
  })

  const onSubmit = handleSubmit((data) => console.log(data))

  return (
    <form onSubmit={onSubmit}>
      <Stack gap="4" align="flex-start" maxW="sm">
        <Field.Root invalid={!!formState.errors.name}>
          <Field.Label>Name</Field.Label>
          <Input placeholder="Enter your name" />
          <Field.ErrorText>{formState.errors.name?.message}</Field.ErrorText>
        </Field.Root>
        <Field.Root invalid={!!formState.errors.dob}>
          <Controller
            control={control}
            name="dob"
            render={({ field }) => (
              <DateInput.Root
                value={field.value}
                onValueChange={(e) => field.onChange(e.value)}
                invalid={!!formState.errors.dob}
              >
                <DateInput.Label>Date of birth</DateInput.Label>
                <DateInput.Control>
                  <DateInput.Segments />
                </DateInput.Control>
                <DateInput.HiddenInput />
              </DateInput.Root>
            )}
          />
          <Field.ErrorText>{formState.errors.dob?.message}</Field.ErrorText>
        </Field.Root>
        <Button type="submit">Submit</Button>
      </Stack>
    </form>
  )
}

